function WorkspaceMenu({activePage,onPage,due}) {
  const [collapsed,setCollapsed]=useState({})
  function render(items) {
    return items.map(item=>{
      const label=item.label||item.page, open=!collapsed[label]
      const selected=activePage===item.page||item.page==='Reports'&&['Business Intelligence','Opportunity Reports','Research Progress'].includes(activePage)
      return <div key={label} className="workspace-nav-item"><div className="workspace-nav-row">
        <button type="button" aria-label={item.accessibilityLabel} className={selected?'active':''} onClick={()=>item.page?onPage(item.page):setCollapsed(c=>({...c,[label]:!c[label]}))}><span aria-hidden="true">{item.children?'◈':'◉'}</span>{label}{item.page==='Follow-Ups'&&due>0&&<b>{due}</b>}</button>
        {item.children&&<button type="button" className="nav-toggle" aria-label={`${open?'Collapse':'Expand'} ${label}`} aria-expanded={open} aria-controls={`nav-${label.replace(/[^a-z0-9]/gi,'-')}`} onClick={()=>setCollapsed(c=>({...c,[label]:!c[label]}))}>{open?'▾':'▸'}</button>}
      </div>{item.children&&<div id={`nav-${label.replace(/[^a-z0-9]/gi,'-')}`} className="workspace-nav-children" hidden={!open}>{render(item.children)}</div>}</div>
    })
  }
  return <nav aria-label="Main navigation">{render(menu)}</nav>
}

