function download(text, filename, type = 'text/csv;charset=utf-8') {
  const blob = new Blob(['\uFEFF', text], { type }); const url = URL.createObjectURL(blob)
  const link = document.createElement('a'); link.href = url; link.download = filename; link.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
function Badge({ value }) { return <span className={`badge ${['Won', 'Active', 'Done', 'Published', 'Replied'].includes(value) ? 'green' : ['Lost', 'Bounced', 'Archived', 'Cancelled'].includes(value) ? 'gray' : 'blue'}`}>{value}</span> }
