 const [profiles,setProfiles]=useState(repository.intelligence?null:[]),[error,setError]=useState(''),[selectedRating,setSelectedRating]=useState(null),[selectedOutreach,setSelectedOutreach]=useState(null),[selectedReview,setSelectedReview]=useState(null)
